              <div>
                <label>MY COMPANY / service provider name</label>
                <input name="service_provider" placeholder="Example: Evolo AI" />
              </div>
              <div>
                <label>Slide count</label>
                <select name="slide_count"><option>3</option><option selected>4</option><option>5</option></select>
              </div>
            </div>
            <div>
              <label>Peer list, if founder provides one</label>
              <input name="peer_list" placeholder="Comma-separated peers. Leave blank to let system select." />
            </div>
            <div>
              <label>Founder source URLs or notes</label>
              <textarea name="source_notes" placeholder="Paste investor-relations URLs, annual reports, press releases, founder notes, or special instructions."></textarea>
