    const form = document.getElementById('dfaForm');
    const step1 = document.getElementById('step1');
    const step2 = document.getElementById('step2');
    const statusEl = document.getElementById('status');
    const resultsEl = document.getElementById('results');
    const runBtn = document.getElementById('runBtn');
    let latest = null;
    function apiBase() { return window.location.origin + '/webhook'; }
    function setText(id, value) { document.getElementById(id).textContent = value || '-'; }
    function copyText(value) { navigator.clipboard.writeText(value || '').catch(() => alert('Copy failed. Select the text manually.')); }
    document.getElementById('nextBtn').addEventListener('click', () => {
      const company = form.company_name.value.trim();
      if (!company) { alert('Please answer Question 1: company name is required.'); return; }
      step1.classList.remove('show');
      step2.classList.add('show');
    });
    document.getElementById('backBtn').addEventListener('click', () => {
      step2.classList.remove('show');
      step1.classList.add('show');
    });
    async function pollResult(resultUrl) {
      for (let attempt = 0; attempt < 120; attempt++) {
        const response = await fetch(resultUrl);
        const data = await response.json();
        if (data.status === 'completed' || data.gamma_markdown) return data;
        if (data.status === 'failed') throw new Error(data.message || 'Production run failed.');
        document.getElementById('statusText').textContent = 'Run ' + (data.run_id || '') + ' is ' + (data.status || 'running') + '. Agents are still working...';
        await new Promise((resolve) => setTimeout(resolve, 5000));
      }
      throw new Error('Run is still processing. Please open the result URL later and check again.');
    }
